package fraymus.workspace;

import org.json.JSONArray;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/** The report is regenerated byte for byte by the Java verifier. */
final class RampMissionReport {
    private RampMissionReport() {}

    static JSONObject build(JSONObject task, JSONObject audit, String sourceCsv) {
        JSONObject source = task.getJSONObject("source"), original = task.getJSONObject("original"), replay = task.getJSONObject("replay");
        JSONArray a = original.getJSONArray("samples"), b = replay.getJSONArray("samples");
        StringBuilder csv = new StringBuilder("tick,time_s,distance_m,replay_distance_m,contacts\n"), rows = new StringBuilder();
        double low = 0, high = 0;
        for (Object item : a) {
            double distance = ((JSONObject) item).getDouble("distanceM");
            low = Math.min(low, distance);
            high = Math.max(high, distance);
        }
        double extent = Math.max(.001, high - low);
        for (int i = 0; i < a.length(); i++) {
            JSONObject sample = a.getJSONObject(i);
            int tick = sample.getInt("tick"), contacts = sample.getInt("contacts");
            double time = sample.getDouble("timeS"), distance = sample.getDouble("distanceM");
            double repeated = b.getJSONObject(i).getDouble("distanceM");
            csv.append(String.format(Locale.ROOT, "%d,%.9f,%.9f,%.9f,%d%n", tick, time, distance, repeated, contacts));
            rows.append(String.format(Locale.ROOT, "<tr><td>%.3f</td><td>%.5f</td><td>%.5f</td><td>%d</td></tr>", time, distance, repeated, contacts));
        }
        String description = RampMission.summary(audit);
        String label = "Input revision " + source.getInt("version");
        var inputs = new StringBuilder();
        for (Object raw : RampInputPage.rows(source.getJSONObject("values"))) {
            JSONObject field = (JSONObject) raw;
            inputs.append("<div><dt>").append(field.getString("label")).append("</dt><dd>")
                    .append(field.getString("value")).append("</dd></div>");
        }
        String html = """
                <!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
                <title>Verified ramp experiment</title><style>
                *{box-sizing:border-box}body{margin:0;background:#111e27;color:#e9f6f2;font:16px/1.5 system-ui}
                main{max-width:880px;margin:auto;padding:clamp(14px,4vw,38px)}h1{margin:.3rem 0;color:#96ead0;line-height:1.15}
                p{margin:.65rem 0}dl{display:flex;flex-wrap:wrap;gap:8px 18px;margin:.5rem 0}dt{font-size:.85rem;color:#b5d3cc}dd{margin:0;font-weight:600}
                svg{display:block;width:100%%;max-height:250px;background:#182d37;margin-top:.7rem}a{color:#96ead0}
                button{background:#96ead0;color:#17332f;border:0;border-radius:5px;padding:.45rem .65rem;font:inherit;cursor:pointer}
                table{border-collapse:collapse;width:100%%;text-align:left}td,th{padding:.45rem;border-bottom:1px solid #435f64}
                .scroller{overflow-x:auto}details{margin-top:.65rem}
                </style><main><small id="revision">%s</small><h1>Verified ramp experiment</h1><p id="result">%s</p><dl>%s</dl>
                <h2>Downhill distance over time</h2><button id="replay-toggle" type="button" aria-pressed="false">Show replay</button>
                <svg role="img" aria-label="Downhill distance in metres over time" viewBox="0 0 600 200">
                <path d="M 25,12 V 174 H 572" fill="none" stroke="#5a7880"/>
                <polyline id="native-line" points="%s" fill="none" stroke="#75edbb" stroke-width="3"/>
                <polyline id="replay-line" points="%s" visibility="hidden" fill="none" stroke="#f9cc83" stroke-width="4" stroke-dasharray="8 5"/>
                <text x="28" y="193" fill="#b5d3cc">0 s</text><text x="530" y="193" fill="#b5d3cc">%.2f s</text>
                </svg><details><summary>Read the samples</summary><div class="scroller"><table><thead><tr><th>Time (s)</th><th>Original (m)</th><th>Replay (m)</th><th>Contacts</th></tr></thead>
                <tbody>%s</tbody></table></div></details>
                <p><a href="samples.csv" download>Download samples</a> · <a href="experiment.json" download>Download evidence</a></p></main>
                <script>
                const button=document.querySelector('#replay-toggle'),line=document.querySelector('#replay-line');
                button.addEventListener('click',()=>{const show=button.getAttribute('aria-pressed')==='false';
                button.setAttribute('aria-pressed',String(show));button.textContent=show?'Hide replay':'Show replay';
                line.setAttribute('visibility',show?'visible':'hidden');});
                </script></html>
                """.formatted(label, description, inputs, points(a, low, extent, audit.getInt("ticks")),
                points(b, low, extent, audit.getInt("ticks")), audit.getDouble("seconds"), rows);
        if (sourceCsv != null) {
            html = html.replace("Download evidence</a></p>", "Download evidence</a> · "
                    + "<a href=\"input.csv\" download>Download original inputs</a></p>");
        }
        var evidence = new JSONObject().put("source", source).put("observation", task.getJSONObject("observation"))
                .put("audit", audit).put("original", original).put("replay", replay);
        var files = new JSONObject().put("index.html", html).put("samples.csv", csv.toString().replace("\r\n", "\n"))
                .put("experiment.json", evidence.toString(2));
        var refs = new ArrayList<>(List.of("artifact:" + source.getString("id") + ":v" + source.getInt("version"),
                "ramp-page:" + source.getString("pageSha256"), "ramp-replay:" + audit.getString("replaySha256")));
        if (sourceCsv != null) {
            files.put("input.csv", sourceCsv);
            refs.add("ramp-csv:" + source.getString("csvSha256"));
        }
        return new JSONObject().put("title", "Verified ramp experiment · v" + source.getInt("version")).put("files", files)
                .put("sources", refs);
    }

    static String points(JSONArray samples, double min, double span, int ticks) {
        StringBuilder out = new StringBuilder();
        for (Object raw : samples) {
            JSONObject sample = (JSONObject) raw;
            double x = 28 + 540.0 * sample.getInt("tick") / ticks;
            double y = 166 - 150.0 * (sample.getDouble("distanceM") - min) / span;
            out.append(String.format(Locale.ROOT, "%.3f,%.3f ", x, y));
        }
        return out.toString().strip();
    }

    static JSONArray checks(JSONObject task) {
        var checks = new JSONArray()
                .put(text("#revision", "Input revision " + task.getJSONObject("source").getInt("version")))
                .put(text("#result", RampMission.summary(task.getJSONObject("audit"))))
                .put(count("tbody tr", task.getJSONObject("audit").getInt("sampleCount")))
                .put(count("a[href='experiment.json'],a[href='samples.csv']", 2))
                .put(count("#replay-line[visibility='hidden']", 1))
                .put(text("#replay-toggle", "Hide replay").put("action", "click"))
                .put(count("#replay-line[visibility='visible']", 1))
                .put(text("#replay-toggle", "Show replay").put("action", "click"))
                .put(count("#replay-line[visibility='hidden']", 1));
        if (task.getJSONObject("source").has("csvSha256")) checks.put(count("a[href='input.csv']", 1));
        return checks;
    }

    static JSONObject text(String selector, String text) {
        return new JSONObject().put("selector", selector).put("expectText", text);
    }
    static JSONObject count(String selector, int count) {
        return new JSONObject().put("selector", selector).put("expectCount", count);
    }

    static boolean verifiedReceipt(JSONObject ref, JSONObject test, JSONArray steps) {
        if (test == null || !test.optBoolean("passed") || !ref.getString("id").equals(test.optString("id"))
                || ref.getInt("version") != test.optInt("version") || !steps.similar(test.optJSONArray("steps"))) return false;
        JSONArray checks = test.getJSONArray("checks");
        if (checks.length() != steps.length()) return false;
        for (int i = 0; i < steps.length(); i++) {
            JSONObject want = steps.getJSONObject(i), got = checks.getJSONObject(i), actual = got.getJSONObject("actual");
            if (got.getInt("index") != i || !got.getBoolean("passed") || !want.similar(got.getJSONObject("expected"))
                    || !want.getString("selector").equals(got.getString("selector"))) return false;
            if (want.has("expectCount") && want.getInt("expectCount") != actual.getInt("count")) return false;
            if (want.has("expectText") && !want.getString("expectText").equals(actual.getString("text").strip())) return false;
        }
        return true;
    }
}
